def iscube(a):
    n = abs(a)
    lo, hi = 0, n + 1
    while lo <= hi:
        mid = (lo + hi) // 2
        c = mid ** 3
        if c == n:
            return True
        if c < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

