def get_max_triples(n):
    c = [0, 0, 0]
    for i in range(1, n + 1):
        c[(i * i - i + 1) % 3] += 1
    c0, c1, c2 = c
    def comb3(x):
        return x * (x - 1) * (x - 2) // 6
    return comb3(c0) + comb3(c1) + comb3(c2) + c0 * c1 * c2

